import{_ as l,o,c as t,a2 as r}from"./chunks/framework.BBdhqAg0.js";const u=JSON.parse('{"title":"거래 내역 관리","description":"","frontmatter":{},"headers":[],"relativePath":"ledger/manage.md","filePath":"ledger/manage.md","lastUpdated":1793109310000}'),e={name:"ledger/manage.md"};function i(n,a,s,d,g,h){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="거래-내역-관리" tabindex="-1">거래 내역 관리 <a class="header-anchor" href="#거래-내역-관리" aria-label="Permalink to &quot;거래 내역 관리&quot;">​</a></h1><p>프로젝트에서 발생하는 모든 실제 입출금 내역을 기록하고, 이를 회계 계정 및 계약 정보와 연결하여 관리하는 핵심 페이지입니다.</p><ul><li><strong>위치</strong>: <code>회계 자금 관리 &gt; 거래 내역 관리</code></li></ul><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>통장상의 실제 거래 데이터(은행거래내역)를 등록하고, 각 거래가 회계상 어떤 의미(분류 내역)를 갖는지 정의합니다. 하나의 거래를 여러 계정으로 나누는 분할 전표 처리를 지원하며, 분양 수입 등 특정 계정의 경우 실제 계약자 정보와 연결하여 수납 장부의 정확성을 확보합니다.</p><h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>상세 필터링 및 검색</strong>: 기간, 계정 과목, 거래 계좌, 계약 정보 등 다양한 조건으로 거래 조회</li><li><strong>다수 거래 일괄 등록</strong>: 한 화면에서 여러 건의 독립된 은행 거래를 동시에 입력 가능</li><li><strong>엑셀 연동</strong>: 분류 내역 엑셀 템플릿 업로드 및 현재 목록의 엑셀 추출 지원</li><li><strong>분할 전표 지원</strong>: 하나의 입/출금 건을 여러 개의 회계 계정으로 상세 분류 가능</li><li><strong>계약/계약자 필수 매칭</strong>: 수납 관련 계정 선택 시 관련 계약 정보를 연동하여 데이터 정합성 유지</li><li><strong>인라인 편집</strong>: 목록 화면에서 적요, 메모, 금액 등을 이동 없이 즉시 수정</li></ul><h2 id="화면-구성" tabindex="-1">화면 구성 <a class="header-anchor" href="#화면-구성" aria-label="Permalink to &quot;화면 구성&quot;">​</a></h2><h3 id="_1-목록-제어-및-필터링" tabindex="-1">1. 목록 제어 및 필터링 <a class="header-anchor" href="#_1-목록-제어-및-필터링" aria-label="Permalink to &quot;1. 목록 제어 및 필터링&quot;">​</a></h3><p>원하는 거래 내역을 신속하게 찾기 위한 검색 영역입니다.</p><ul><li><strong>검색 조건</strong>: 거래일자 범위, 입출금 구분, 계정 분류(자산/부채/수익/비용 등), 상세 계정 과목, 거래 계좌 등</li><li><strong>전체(운영비용 포함) 보기</strong>: 체크 시 일반 사업비 외에 운영비용(전도금) 계좌의 내역까지 통합 조회합니다.</li></ul><h3 id="_2-입출금-현황-목록" tabindex="-1">2. 입출금 현황 목록 <a class="header-anchor" href="#_2-입출금-현황-목록" aria-label="Permalink to &quot;2. 입출금 현황 목록&quot;">​</a></h3><p>조회된 거래 내역을 표시하며, 각 행은 &#39;은행거래내역&#39;과 &#39;분류 내역&#39;으로 나뉩니다.</p><ul><li><strong>은행거래내역</strong>: 실제 통장에 기록된 날짜, 계좌명, 적요, 입/출금액 정보</li><li><strong>분류 내역</strong>: 해당 거래가 회계 장부에 기록되는 계정명, 거래처, 분류 금액 및 지출 증빙 정보</li><li><strong>금액 검증</strong>: 은행 거래 금액과 하단 분류 내역의 합계가 일치하면 초록색 체크 아이콘(✅)이 표시됩니다. 일치하지 않을 경우 경고 메시지와 함께 차액을 안내합니다.</li></ul><h3 id="_3-거래-등록-및-수정" tabindex="-1">3. 거래 등록 및 수정 <a class="header-anchor" href="#_3-거래-등록-및-수정" aria-label="Permalink to &quot;3. 거래 등록 및 수정&quot;">​</a></h3><p>새로운 입출금 내역을 생성하거나 기존 내역을 상세 수정하는 화면입니다.</p><ul><li><strong>은행거래건 추가</strong>: 신규 등록 시 여러 건의 거래를 한 번에 추가하여 작업 시간을 단축할 수 있습니다.</li><li><strong>이체수수료 자동 입력</strong>: 출금 항목 옆의 아이콘을 클릭하면 설정된 이체 수수료(예: 500원) 분개를 자동으로 생성합니다.</li><li><strong>대체 거래 자동 감지</strong>: 출금 거래 시 &#39;대체(출금)&#39; 계정을 선택하면, 상대 계좌로 들어오는 &#39;대체(입금)&#39; 거래건을 시스템이 자동으로 추가 생성합니다.</li></ul><h2 id="📊-대량-엑셀-업로드-가이드-bulk-excel-import" tabindex="-1">📊 대량 엑셀 업로드 가이드 (Bulk Excel Import) <a class="header-anchor" href="#📊-대량-엑셀-업로드-가이드-bulk-excel-import" aria-label="Permalink to &quot;📊 대량 엑셀 업로드 가이드 (Bulk Excel Import)&quot;">​</a></h2><p>대량의 공사비 집행, 외주 용역비 정산, 다수 계약자의 일괄 수납 내역 등을 엑셀 템플릿을 통해 한 번에 입력할 수 있습니다.</p><h3 id="_1-템플릿-다운로드-및-시트-구성" tabindex="-1">1. 템플릿 다운로드 및 시트 구성 <a class="header-anchor" href="#_1-템플릿-다운로드-및-시트-구성" aria-label="Permalink to &quot;1. 템플릿 다운로드 및 시트 구성&quot;">​</a></h3><p>화면 우측 상단의 <strong>[엑셀 템플릿 다운로드]</strong> 버튼을 클릭하면 3개의 시트로 구성된 스마트 엑셀 파일이 다운로드됩니다:</p><ol><li><strong>거래내역 대량입력 (메인 시트)</strong>: 실제 거래 및 회계 분개 데이터를 입력하는 시트입니다.</li><li><strong>작성안내 시트</strong>: 그룹번호 작성 원리, 지출증빙 코드(세금계산서, 카드, 계산서, 간이영수증 등), 필수 주의사항이 상세히 안내되어 있습니다.</li><li><strong>참조목록 시트</strong>: 현재 프로젝트(본사)에 등록된 <strong>정확한 거래계좌명</strong>과 <strong>회계 계정과목명</strong>이 나열되어 있어, 오타 없이 복사하여 붙여넣을 수 있습니다.</li></ol><h3 id="_2-그룹번호-1-n-분할-전표-작성-방법" tabindex="-1">2. 그룹번호(1:N 분할 전표) 작성 방법 <a class="header-anchor" href="#_2-그룹번호-1-n-분할-전표-작성-방법" aria-label="Permalink to &quot;2. 그룹번호(1:N 분할 전표) 작성 방법&quot;">​</a></h3><p>하나의 은행 통장 거래를 여러 회계 계정으로 나누어 분개할 때는 **[그룹번호]**를 활용합니다:</p><ul><li><strong>단일 거래 (1:1 분개)</strong>: <ul><li>1행: 그룹번호 <code>1</code>, 거래일자, 계좌, 적요, 출금 100만원 → 계정(공사비), 분류금액 100만원 입력.</li></ul></li><li><strong>분할 거래 (1:N 분개)</strong>: <ul><li>1행: 그룹번호 <code>2</code>, 거래일자, 계좌, 적요, 출금 150만원 → 계정A, 분류금액 100만원 입력.</li><li>2행: 그룹번호 <code>2</code>, <strong>은행거래 정보는 빈칸</strong> → 계정B, 분류금액 50만원 입력.</li><li>※ 같은 그룹번호에 속한 분류금액 합계(100만 + 50만)는 은행 출금액(150만)과 반드시 일치해야 합니다.</li></ul></li></ul><h3 id="_3-시스템별-맞춤형-연관-열" tabindex="-1">3. 시스템별 맞춤형 연관 열 <a class="header-anchor" href="#_3-시스템별-맞춤형-연관-열" aria-label="Permalink to &quot;3. 시스템별 맞춤형 연관 열&quot;">​</a></h3><ul><li><strong>프로젝트 자금 관리</strong>: <strong><code>계약자</code></strong> 열이 제공되며, 분양 수입 등 계약 관련 계정 입력 시 계약자 정보를 사전에 매핑할 수 있습니다.</li><li><strong>본사 자금 관리</strong>: <strong><code>관계회사(프로젝트)</code></strong> 열이 제공되어, 각 프로젝트별 대여금이나 전도금 지출 내역을 매핑할 수 있습니다.</li></ul><h3 id="_4-사전-검증-및-미리보기-bulk-upload-dialog" tabindex="-1">4. 사전 검증 및 미리보기 (Bulk Upload Dialog) <a class="header-anchor" href="#_4-사전-검증-및-미리보기-bulk-upload-dialog" aria-label="Permalink to &quot;4. 사전 검증 및 미리보기 (Bulk Upload Dialog)&quot;">​</a></h3><p>작성한 엑셀 파일을 업로드하면 시스템이 저장 전 <strong>사전 검증 미리보기 창</strong>을 띄웁니다:</p><ul><li><strong>행 단위 정밀 검증</strong>: 날짜 형식 오류, 미등록 계정명, 입출금액과 분류금액 불일치 건을 사전에 감지하여 붉은색 경고(✖)로 표시합니다.</li><li><strong>정상 거래만 선택 반영</strong>: 오류가 포함된 거래는 자동으로 제외하고, 정상 검증된 건만 폼에 안전하게 반영할 수 있습니다.</li><li><strong>반영 방식 선택 (스위치)</strong>: <ul><li><code>현재 입력 내용 대체</code>: 기존에 작성 중이던 폼을 비우고 엑셀 데이터로 교체합니다.</li><li><code>현재 입력 내용 뒤에 추가</code>: 기존 작성 중이던 거래 뒤에 이어서 추가합니다.</li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">💡 2단계 안전 저장 프로세스 (Pre-apply → Final Save)</p><p>엑셀을 업로드하더라도 데이터베이스에 즉시 저장되지 않고 <strong>화면 입력 폼으로 먼저 불러와집니다</strong>. 화면에서 데이터가 올바른지 최종 검토한 후 상단의 <strong>[생성]</strong> 버튼을 클릭해야 데이터베이스에 최종 저장되므로 데이터 오염 사고를 원천 방지합니다.</p></div><div class="warning custom-block"><p class="custom-block-title">⚠️ 1회 업로드 권장 상한선</p><p>브라우저 메모리 및 렌더링 안정성을 위해 <strong>1회 업로드 시 은행거래 50건 / 회계계정 200행 이하</strong>로 작성하는 것을 권장합니다. 대량의 데이터는 파일을 나누어 순차적으로 등록해 주십시오.</p></div><h2 id="💡-주요-관리-포인트" tabindex="-1">💡 주요 관리 포인트 <a class="header-anchor" href="#💡-주요-관리-포인트" aria-label="Permalink to &quot;💡 주요 관리 포인트&quot;">​</a></h2><h3 id="계정별-필수-정보-매칭" tabindex="-1">계정별 필수 정보 매칭 <a class="header-anchor" href="#계정별-필수-정보-매칭" aria-label="Permalink to &quot;계정별 필수 정보 매칭&quot;">​</a></h3><p>분양수입, 미수금, 미지급금 등 <strong>계약 정보와 직접 연결되는 계정</strong>을 선택하면 시스템이 자동으로 [계약 정보 선택] 창을 띄웁니다. 이를 통해 수납 관리 메뉴와 회계 관리 메뉴의 데이터가 완벽하게 일치하게 됩니다.</p><h3 id="수정-제한-정산-보호" tabindex="-1">수정 제한 (정산 보호) <a class="header-anchor" href="#수정-제한-정산-보호" aria-label="Permalink to &quot;수정 제한 (정산 보호)&quot;">​</a></h3><p>정산이 완료된 일자 이전의 거래나 특정 기간(기본 10일)이 지난 과거 데이터는 데이터 무결성을 위해 일반 권한으로 수정이 제한될 수 있습니다. 중요한 과거 데이터 수정은 관리자에게 문의하십시오.</p>',37)])])}const p=l(e,[["render",i]]);export{u as __pageData,p as default};
